USE `remixd`;

#SELECT * FROM Account;
#SELECT * FROM Review;
SELECT * FROM Tags;
SELECT ReviewAccountID, ReviewAlbumID, COUNT(*) as Reports FROM Tags WHERE ((info & 64) = 64) GROUP BY ReviewAccountID, ReviewAlbumID ORDER BY Reports DESC LIMIT 5;
#SELECT IF(info & 128 = 128, True, False) FROM Tags;
